INSERT INTO `about_us` VALUES (1,1,'https://api.derexqa.online/uploads/image-webp/team-derex_1774309578500.webp','Historia Javer',0,'<p style=\"text-align:center;\"><span style=\"font-size: 48px;font-family: Arial;\"><strong>Nuestra Misión y Valores</strong></span></p>\n<p><span style=\"font-size: 48px;font-family: Arial;\"><strong><br></strong></span><span style=\"font-size: 24px;font-family: Arial;\"><strong>Misión</strong></span></p>\n<p style=\"text-align:left;\"><span style=\"font-family: Arial;\">Enfocar nuestra experiencia como desarrolladores al servicio de nuestros clientes, ofreciéndoles la mejor opción para vivir, dentro de un entorno habitacional sano y estimulante, en donde se cultiven los principios de convivencia familiar y comunitaria, así como la armonía con el medio ambiente. <br><br>Buscamos también, que esta actividad inspire el máximo desarrollo de nuestras potencialidades individuales y de grupo, trabajando en equipo, con calidad y apegados a nuestros principios de responsabilidad, honestidad y ética.<br><br><br></span></p>\n<p><span style=\"font-size: 24px;font-family: Arial;\"><strong>Valores<br></strong></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">· </span><span style=\"font-family: Arial;\">Honestidad y ética<br>· Responsabilidad<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Pasión por el trabajo y esfuerzo<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Confianza y buena voluntadTrabajo en equipo<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Cultura de calidad<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Respeto a las personas y el entorno físico<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Valorar la diversidad de ideas<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Sensibilidad a la realidad social<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Solidaridad y espíritu de servicio<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Aprecio por la salud y la integridad física<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-family: Arial;\">Buen humor y optimismo</span></p>\n','<p style=\"text-align:center;\"><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 48px;font-family: Arial;\"><strong>Our Mission and Values</strong></span></p>\n<p><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 24px;font-family: Arial;\"><strong><br>Mission</strong></span></p>\n<p><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">To focus our experience as developers on serving our clients, offering them the best living options within a healthy and stimulating residential environment, where the principles of family and community life are cultivated, as well as harmony with the environment.<br><br></span></p>\n<p><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">We also seek to inspire the maximum development of our individual and group potential through teamwork, quality, and adherence to our principles of responsibility, honesty, and ethics.<br><br></span><span style=\"font-size: 24px;font-family: Arial;\"><strong>Values</strong></span></p>\n<p><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Honesty and ethics<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Responsibility<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Passion for work and effort<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Trust and goodwill<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Teamwork<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Culture of quality<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Respect for people and the physical environment<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Valuing the diversity of ideas<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Sensitivity to social realities<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Solidarity and a spirit of service<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Appreciation for health and physical integrity<br></span><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">·</span> <span style=\"font-size: 16px;font-family: Arial;\">Good humor and optimism</span></p>\n','2026-03-05 18:38:00','2026-04-13 07:14:01'),(2,0,'https://api.derexqa.online/uploads/image-webp/derex-team_1774378144572.webp','Historia Javer',1,'<p style=\"text-align:center;\"><span style=\"font-size: 48px;\"><strong>Conoce </strong></span><span style=\"color: rgb(41,105,176);font-size: 48px;\"><strong>Derex<br></strong></span></p>\n<p><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 24px;font-family: Arial;\"><strong><br>Comunidad<br></strong></span></p>\n<p style=\"text-align:left;\"><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">Entorno sano y agradable, organización vecinal, promotores vecinales, programas de actividades comunitarias, ecológicas, deportivas y culturales; respeto a las personas y amor por México.<br><br></span></p>\n<p style=\"text-align:left;\"><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 24px;font-family: Arial;\"><strong>Entorno<br></strong></span></p>\n<p style=\"text-align:left;\"><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">La propuesta incluye: imagen urbana residencial, plaza o punto de reunión, vegetación endémica, avenidas de concreto, arborización adicional y consideraciones para personas con discapacidad.<br><br></span></p>\n<p style=\"text-align:left;\"><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 24px;font-family: Arial;\"><strong>Innovacion<br></strong></span></p>\n<p style=\"text-align:left;\"><span style=\"color: rgb(33,43,54);background-color: rgb(255,255,255);font-size: 16px;font-family: Arial;\">Plataforma de nuevos programas y proyectos piloto propuestos por diferentes instituciones y organismos a nivel nacional e internacional. Ligada a la innovación, la sustentabilidad, más que una moda, es para cada colaborador, el motor de su actividad.</span><span style=\"font-family: Arial;\"> </span></p>\n','<p style=\"text-align:center;\"><span style=\"font-size: 48px;font-family: Arial;\"><strong>Meet </strong></span><span style=\"color: rgb(41,105,176);font-size: 48px;font-family: Arial;\"><strong>Derex <br></strong></span></p>\n<p></p>\n<p><span style=\"font-size: 24px;font-family: Arial;\"><strong><br>Community </strong></span></p>\n<p></p>\n<p><span style=\"font-family: Arial;\">A healthy and pleasant environment, neighborhood organization, community promoters, community, ecological, sports, and cultural activity programs; respect for people and love for Mexico. <br></span></p>\n<p><span style=\"font-family: Arial;\"><br></span></p>\n<p><span style=\"font-size: 24px;font-family: Arial;\"><strong>Environment</strong></span></p>\n<p><span style=\"font-family: Arial;\">The proposal includes: a residential urban design, a plaza or meeting point, native vegetation, concrete avenues, additional tree planting, and accessibility features for people with disabilities. <br><br></span></p>\n<p></p>\n<p><span style=\"font-size: 24px;font-family: Arial;\"><strong>Innovation</strong></span></p>\n<p><span style=\"font-family: Arial;\">A platform for new programs and pilot projects proposed by various national and international institutions and organizations. Linked to innovation, sustainability is more than just a trend; for each employee, it is the driving force behind their work.</span></p>\n','2026-03-20 17:19:39','2026-04-13 07:14:01');
