INSERT INTO `certifications` VALUES (2,'JAVER es ESR por noveno año consecutivo.','JAVER es ESR por noveno año consecutivo.','Manteniendo nuestro compromiso con la sostenibilidad y esfuerzos por la mejora continua, hemos recibido por novena ocasión el Distintivo ESR (Empresa Socialmente Responsable) otorgado por el Centro Mexicano para la Filantropía (CEMEFI).','Manteniendo nuestro compromiso con la sostenibilidad y esfuerzos por la mejora continua, hemos recibido por novena ocasión el Distintivo ESR (Empresa Socialmente Responsable) otorgado por el Centro Mexicano para la Filantropía (CEMEFI).','2026-03-11','https://javer.com.mx/blog/recibimos-nuestro-9-distintivo-esr','https://javer.com.mx/blog/recibimos-nuestro-9-distintivo-esr',0,'2026-03-20 18:31:35','2026-03-20 18:31:35','https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/esr-horizontal_1773245255440.webp','JAVER es ESR por noveno año consecutivo',0),(3,'JAVER obtiene el certificado GPTW por 8vo Año','JAVER get the GPTW certificate for the 8th Year','En Javer estamos orgullosos de anunciar que hemos recibido, por octavo año consecutivo, la certificación como uno de los Mejores Lugares para Trabajar.','At Javer we are proud to announce that we have received, for the eighth consecutive year, the certification as one of the Best Places to Work.','2024-11-21','https://javer.com.mx/blog/8va-certificaci%C3%B3n-javer-great-place-to-work',NULL,0,'2026-03-20 18:31:35','2026-03-20 18:31:35','https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/grate-place-to-work-certificacion-javer_1773263952898.webp','GPTW PREMIO JAVER',0),(4,' JAVER se adhiere al UN Global Compact',' JAVER se adhiere al UN Global Compact','El Pacto Mundial es un llamado a que las empresas del mundo para que adapten sus estándares y operaciones a 10 principios universales que permiten tomar medidas sobre acciones de derechos humanos, estándares laborales,medio ambiente y anticorrupción.','The Global Compact is a call for companies worldwide to align their standards and operations with 10 universal principles that address human rights, labor standards, environmental issues, and anti-corruption measures.','2021-08-31','https://ri.javer.com.mx/contribucion-ods?_gl=1*wsf6hv*_gcl_aw*R0NMLjE3Mjg1NzUxNzMuQ2p3S0NBanc3NzZNVkFrVU4fQ0NMLjE3Mjg1NzUxNzMuQ2p3S0NBanc3NzZNVkFrVU4fQ0NMLjE3Mjg1NzUxNzMuQ2p3S0NBanc3NzZNVkFrVU4fQ0NMLjE3Mjg1NzUxNzMuQ2p3S0NBanc3NzZNVkFrVU4',NULL,0,'2026-03-20 18:31:35','2026-03-20 18:31:35','https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/javer-UN-Global-Compact_1773264072978.webp','Javer se une UN Global Compact',0),(5,'JAVER recibe mención honorífica de CONCAMIN.','JAVER recibe mención honorífica de CONCAMIN.','JAVER fue galardonada con mención honorífica en la categoría de Empresas Grandes por la Confederación de Cámaras Industriales (CONCAMIN) en el Premio Ética y Valores, destacando su compromiso con la responsabilidad social y sus valores diarios.','JAVER was awarded an honorable mention in the Large Companies category by the Confederation of Industrial Chambers (CONCAMIN) in the Ethics and Values Award, highlighting its commitment to social responsibility and daily values.','2021-08-31','https://javer.com.mx/blog/segundo-a%C3%B1o-obteniendo-el-premio-concamin-%7C-javer',NULL,0,'2026-03-20 18:31:35','2026-03-20 18:31:35','https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/JAVER-recibe-mencion-honorifica-de-CONCAMIN_1773264256249.webp','JAVER recibe mención honorífica de CONCAMIN',0),(6,' JAVER es EDGE Champion',' JAVER es EDGE Champion','En 2022, JAVER obtuvo la certificación EDGE para dos proyectos, asegurando viviendas con ahorros en agua y electricidad, y que además utilizan materiales con menor impacto ambiental, contribuyendo a la sustentabilidad y beneficios para los clientes.','In 2022, JAVER certified two projects with EDGE, ensuring homes that save water and electricity while using materials with lower environmental impact, contributing to sustainability and offering benefits to customers','2023-11-13','https://ri.javer.com.mx/blog/javer-es-edge-champion',NULL,0,'2026-03-20 18:31:35','2026-03-20 18:31:35','https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/JAVER-obtuvo-la-certificacion-EDGE_1773264390111.webp','JAVER obtuvo la certificación EDGE',0);
/*!40000 ALTER TABLE `certifications` ENABLE KEYS */;
UNLOCK TABLES;

