INSERT INTO `frequent_questions` VALUES (1,'¿Qué tipo de crédito puedo utilizar para adquirir mi vivienda?','Los créditos compatibles para adquirir tu vivienda Derex son Infonavit (tradicional o conyugal), FOVISSSTE, Bancario, Cofinavit, Unamos créditos y FOVISSSTE para todos.','What type of loan can I use to finance my home?','The compatible financing options for purchasing your Derex home include Infonavit (traditional or conjugal), FOVISSSTE, Bank Financing, Cofinavit, \'Unamos Créditos,\' and \'FOVISSSTE para Todos\'. ',NULL,0,'2024-10-12 04:12:44','2024-10-12 04:12:44'),(2,'¿Cuál es el tiempo de entrega de mi vivienda?','Las casas se entregan aproximadamente en un periodo de 30 a 45 días hábiles después de la firma de las escrituras.','What is the delivery time for my home?','Homes are delivered approximately 30 to 45 business days after the deeds are signed.',NULL,0,'2024-10-12 04:21:19','2024-10-12 04:21:19'),(3,'¿Aceptan Infonavit?','Sí, tu crédito Infonavit es compatible para adquirir tu vivienda Derex.','Do you accept Infonavit?','Yes, your Infonavit loan is compatible for purchasing a Derex home.',NULL,0,'2024-10-12 04:23:09','2024-10-12 04:23:09'),(5,'¿Pueden checar mis puntos Infonavit?','Te invitamos a registrarte en la siguiente liga para que estés al tanto de cumplir con los requisitos necesarios, aquí mismo puedes ver la fecha en que se libera tu crédito o tu precalificación.','Can I check my Infonavit points?','We invite you to register at the following link so you can stay informed about the necessary requirements. Here, you can also see the date when your credit or prequalification is released.','https://micuenta.infonavit.org.mx',0,'2024-10-12 04:25:23','2024-10-12 04:25:23'),(6,'¿Cuántos puntos necesito para adquirir mi vivienda Derex?','Infonavit requiere 1080 puntos para poder liberar tu crédito y el monto del mismo varía de acuerdo a tu tiempo cotizando, tu ingreso mensual y más situaciones.','How many points do I need to purchase my Derex home?','Infonavit requires 1080 points to release your loan, and the amount varies based on your time contributing, monthly income, and other factors.',NULL,0,'2024-10-12 04:26:53','2024-10-12 04:26:53');
/*!40000 ALTER TABLE `frequent_questions` ENABLE KEYS */;
UNLOCK TABLES;

