INSERT INTO `meta` VALUES (1,'home','home_main_title','Encuentra tu nuevo hogar','Find your new home',1,0,0),(2,'home','home_subtitle','Proyectos disponibles en tu ciudad','Projects available in your city',0,0,0),(3,'meet-javer','titleUpper','Conoce','Meet',1,0,0),(4,'meet-javer','titleLower','DEREX','DEREX',0,0,1),(5,'meet-javer','description','<p style=\"text-align:start;\"><span style=\"color: rgb(23,23,23);background-color: rgb(255,255,255);font-size: 18px;font-family: Arial;\">En Derex, nos dedicamos al desarrollo de viviendas innovadoras, sostenibles y diseñadas para crear comunidades ideales para el bienestar de las familias en México. Gracias a la experiencia de nuestra empresa y el trabajo de nuestros expertos podrás tener la certeza de que aquí encontrarás el patrimonio que siempre deseaste.</span></p>\n','<p><span style=\"color: rgb(23,23,23);background-color: rgb(255,255,255);font-size: 18px;font-family: Arial;\">At Derex, we are dedicated to developing innovative, sustainable homes designed to create ideal communities for the well-being of families in Mexico. Thanks to our company\'s experience and the work of our experts, you can be confident that you will find the home you\'ve always dreamed of here.</span></p>\n',0,0,0),(6,'meet-javer','buttonText','Conoce más','Learn more',0,0,0),(12,'about-us','aboutJaver_mainTitle','Nosotros','About us',1,0,0),(13,'about-us','aboutJaver_bannerUrl','https://www.javer.com.mx/images/website/home.webp','https://www.javer.com.mx/images/website/home.webp',0,0,0),(14,'home','home_search','Encuentra tu nuevo hogar','Find your new home',1,0,0),(15,'home','home_featuredDevelopmentsUp','Desarrollos Destacados','Featured Projects',1,0,0),(16,'home','home_featuredDevelopmentsDown','Desarrollos Destacados','Featured Projects',1,0,0),(17,'home','home_blogJaver','Blog Derex','Derex Blog',1,0,0),(18,'home','home_customerExperience','Conoce la experiencia de nuestros clientes','Conoce la experiencia de nuestros clientes',1,0,0),(19