DROP TABLE IF EXISTS `property`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `property` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `id_project` int unsigned DEFAULT NULL,
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vertical_floor` int DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `description_eng` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT (`description`),
  `rooms` int DEFAULT NULL,
  `bathrooms` int DEFAULT NULL,
  `restrooms` int DEFAULT NULL,
  `delivery_status` enum('ready_to_move','white building','gray building','preesale') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `construction_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `architectural_plans_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `360_video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `materport_video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cars_garage_capacity` int DEFAULT NULL,
  `cars_parking_lot_capacity` int DEFAULT '0',
  `floors` int DEFAULT NULL,
  `square_meters` float DEFAULT NULL,
  `price_base_mxn` float DEFAULT NULL,
  `price_m2_extra_mxn` float DEFAULT NULL,
  `ubication` int DEFAULT NULL,
  `email_contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `featured` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active` tinyint(1) DEFAULT '1',
  `main_image` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `main_image_alt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `main_image_vertical` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `project_order` int DEFAULT NULL,
  `banner` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `virtual_tour_iframe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `features` json DEFAULT NULL,
  `isEdgeCertified` tinyint(1) NOT NULL DEFAULT '0',
  `additional_info` json DEFAULT NULL,
  `outstanding` tinyint(1) DEFAULT '0',
  `thumbnail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `thumbnail_alt_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `property_project_fk` (`id_project`)
) ENGINE=InnoDB AUTO_INCREMENT=350 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
