INSERT INTO `property` VALUES (1,1,'casa',NULL,'Modelo Roble','Roble','Casa demo de 2 recámaras y patio.','Casa demo de 2 recámaras y patio.',2,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,2,78,1450000,NULL,NULL,NULL,NULL,'1',1,'https://www.javer.com.mx/images/website/home.webp','Modelo Roble',NULL,'2026-03-05 18:38:00','2026-03-05 18:38:00',NULL,NULL,NULL,NULL,0,NULL,1,'https://www.javer.com.mx/images/website/home.webp','Thumb Roble'),(2,1,'casa',NULL,'Modelo Encino','Encino','Casa demo con recámara en planta baja.','Casa demo con recámara en planta baja.',3,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,2,92,1690000,NULL,NULL,NULL,NULL,'1',1,'https://www.javer.com.mx/images/website/home.webp','Modelo Encino',NULL,'2026-03-05 18:38:00','2026-03-05 18:38:00',NULL,NULL,NULL,NULL,0,NULL,0,'https://www.javer.com.mx/images/website/home.webp','Thumb Encino'),(3,2,'departamento',NULL,'Modelo Nube','Nube','Departamento demo de excelente ubicación.','Departamento demo de excelente ubicación.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,64,1320000,NULL,NULL,NULL,NULL,'1',1,'https://www.javer.com.mx/images/website/home.webp','Modelo Nube',NULL,'2026-03-05 18:38:00','2026-03-05 18:38:00',NULL,NULL,NULL,NULL,0,NULL,1,'https://www.javer.com.mx/images/website/home.webp','Thumb Nube'),(4,3,'casa',NULL,'Modelo Ceiba','Ceiba','Casa demo de 3 recámaras con roof.','Casa demo de 3 recámaras con roof.',3,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,2,105,1990000,NULL,NULL,NULL,NULL,'0',1,'https://www.javer.com.mx/images/website/home.webp','Modelo Ceiba',NULL,'2026-03-05 18:38:00','2026-03-05 18:38:00',NULL,NULL,NULL,NULL,0,NULL,1,'https://www.javer.com.mx/images/website/home.webp','Thumb Ceiba'),(68,42,'1',NULL,'Agave Plus',NULL,'Nuestro modelo Agave fue diseñado para crear un ambiente espacioso y luminoso. Ofrece de inmediato un sentimiento de bienestar y comodidad con una distribución ideal para comenzar una nueva vida en familia.','Our agave model was designed to create a spacious and bright atmosphere. It immediately offers a feeling of well -being and comfort with an ideal distribution to start a new family life.',2,2,0,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1691790725_privalia.mp4','https://my.matterport.com/show/?m=ib8rFhNXNiV',0,2,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758240806930.jpg',NULL,NULL,'2026-03-20 00:25:31','2026-03-20 00:25:31',0,NULL,'<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=uJjhMxCsMk8\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758240823338.jpg',NULL),(85,45,'1',NULL,'Orión Plus',NULL,'Este no es solo un modelo, es el refugio de la felicidad y la realización de tus anhelos. En Orión Plus, la magia de la vida cobra vida, y cada rincón se convierte en un escenario para tus aventuras familiares más especiales.\n\n¡Bienvenidos a un mundo de emociones en tu nuevo hogar en Playa del Carmen!','This is not just a model, it is the refuge of happiness and the fulfillment of your desires. In Orión Plus, the magic of life comes to life, and every corner becomes a stage for your most special family adventures.\n\nWelcome to a world of emotions in your new home in Playa del Carmen!',2,1,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1606436814_Portoalto_crop_1.mp4','https://my.matterport.com/show/?m=SQ2MiZmbyXi',1,0,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758556851274.jpg',NULL,NULL,'2026-03-20 00:36:45','2026-03-20 00:36:45',0,NULL,'<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=SQ2MiZmbyXi\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1730239347036.png',NULL),(86,45,'1',NULL,'Bari Premier',NULL,'Bari Premier es mucho más que un modelo; es la llave que abrirá las puertas de la vida que sueñas. Este hogar se convertirá en tu refugio de alegría y la base de tus aspiraciones. Aquí, cada día es una oportunidad para alcanzar tus metas y disfrutar de la vida al máximo. Si buscas un lugar donde tus sueños se hagan realidad, Bari Premier es la elección perfecta.\n\n¡Bienvenidos a una vida llena de emociones y logros!','Bari Premier is much more than a model; It is the key that will open the doors of the life you dream of. This home will become your refuge of joy and the basis of your aspirations. Here, every day is an opportunity to achieve your goals and enjoy life to the fullest. If you are looking for a place where your dreams come true, Bari Premier is the perfect choice.\n\nWelcome to a life full of emotions and achievements!',2,2,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1606436814_Portoalto_crop_1.mp4','https://my.matterport.com/show/?m=P91e7BAat9E',1,0,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758557770539.jpg',NULL,NULL,'2026-03-20 00:36:45','2026-03-20 00:36:45',0,NULL,'<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=P91e7BAat9E\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758557836054.jpg',NULL),(87,45,'1',NULL,'Milán Premier',NULL,'Tu nuevo estilo de vida te espera con el modelo Milán Premier, donde podrás iniciar a hacer tus sueños realidad cerca de la playa.','Your new lifestyle awaits you with the Milan Premier model, where you can start making your dreams come true near the beach.',2,2,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1606436814_Portoalto_crop_1.mp4','https://my.matterport.com/show/?m=KSbdJEnexJX',1,0,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758559692657.jpg',NULL,NULL,'2026-03-20 00:36:45','2026-03-20 00:36:45',0,NULL,'<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=KSbdJEnexJX\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1730239305605.png',NULL),(91,51,'1',NULL,'Albatros',NULL,'Nuestro modelo Albatros cuenta con una excelente distribución, nuestras amplias recamaras, baño completo, área de lavandería y cochera para tu auto hacen de nuestro diseño la mejor opción para que tú y tu familia disfruten de su hogar y diseñadas para adecuarse a tus futuras necesidades.','Our Albatros model has an excellent distribution, our large bedrooms, full bathroom, laundry area and garage for your car make our design the best option for you and your family to enjoy your home and designed to adapt to your future needs.',2,1,0,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1677612040_Tamps_Piramides_portada 1920x790_feb.mp4','https://my.matterport.com/show/?m=L7g9SsZNfCi',1,0,2,0,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/1758649075186.webp',NULL,NULL,'2026-03-19 16:28:05','2026-03-19 16:28:05',0,'','<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=L7g9SsZNfCi\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,'{}',0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/1758649084962.webp',NULL),(134,43,'1',NULL,'Alba Roof Garden Plus',NULL,'Disfruta de uno de nuestros modelos preferidos, con espacios confortables para ti y tu familia. El protagonista de este modelo sin duda es su patio de gran tamaño donde comenzarás a crear esos momentos inigualables en familia.','Disfruta de uno de nuestros modelos preferidos, con espacios confortables para ti y tu familia. El protagonista de este modelo sin duda es su patio de gran tamaño donde comenzarás a crear esos momentos inigualables en familia.',3,3,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1691791923_massaro.mp4','https://my.matterport.com/show/?m=4vMpV9zZqJk',2,0,3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/1758296209133.webp',NULL,NULL,'2026-03-20 00:29:30','2026-03-20 00:29:30',0,NULL,'<iframe width=\'100%\' height=\'480\' src=\'https://my.matterport.com/show/?m=DPWZo3xqTZD\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/1758296217524.webp',NULL),(137,45,'1',NULL,'Mira Elite',NULL,'Un modelo lleno de comodidad y bienestar para ti y tu familia. Comienza a crear grandes recuerdos con tus seres queridos y empieza a llamarlo Hogar.','A model full of comfort and well-being for you and your family. Start creating great memories with your loved ones and start calling it Home.',3,2,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1606436814_Portoalto_crop_1.mp4','',2,0,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758560921643.jpg',NULL,NULL,'2026-03-20 00:36:45','2026-03-20 00:36:45',0,NULL,'<iframe loading=\"lazy\" width=\"100%\" height=\"580\" src=\"https://my.matterport.com/show/?m=dWAssZSBwL7\" frameborder=\"0\" allowfullscreen allow=\"autoplay; fullscreen; web-share; xr-spatial-tracking;\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1758565287696.jpg',NULL),(143,42,'1',NULL,'Mezquite',NULL,'Su excelente distribución permite aprovechar cada metro, siendo el protagonista nuestro prototipo con Roof Garden, que cuenta con una orientación y vistas inigualables para disfrutar de grandes momentos en familia.','Its excellent distribution allows you to take advantage of every meter, the protagonist being our prototype with Roof Garden, which has an unparalleled orientation and views to enjoy great family moments.',2,2,0,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1691790725_privalia.mp4','https://my.matterport.com/show/?m=mpvpD4WzJaJ',0,2,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/1758242078735.webp',NULL,NULL,'2026-03-20 00:25:31','2026-03-20 00:25:31',0,NULL,'<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=mpvpD4WzJaJ\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-webp/1758242088504.webp',NULL),(145,14,'1',NULL,'Aura Elite',NULL,'Nuestro modelo Aura Elite está diseñado para que aproveches al máximo todos sus espacios y su distribución te permita vivir de manera cómoda. Aprovecha un amplio patio para tus reuniones familiares y descubre la perfecta armonía entre la sofisticación y la calidez que te espera en cada rincón.','Our Aura Elite model is designed so that you can make the most of all its spaces and its distribution allows you to live comfortably. Take advantage of a large patio for your family gatherings and discover the perfect harmony between sophistication and warmth that awaits you in every corner.',3,2,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1675190915_MDLA Video portada 20s cambios_2.mp4','https://my.matterport.com/show/?m=MYuAKerRZs2',2,0,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-png/1757022938757.png',NULL,NULL,'2026-03-19 17:50:23','2026-03-19 17:50:23',0,NULL,'<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=MYuAKerRZs2\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-png/1757022949826.png',NULL),(169,39,'1',NULL,'Blanc',NULL,'Modelo Blanc destaca por su diseno funcional y espacios luminosos. Esta residencia inteligente ofrece 4 habitaciones, distribuidas en 3 en la planta alta y 1 en la planta baja, ademas de un jardin trasero ideal para compartir momentos en familia.','Modelo Blanc stands out for its functional design and bright spaces. This intelligent residence offers 4 bedrooms, distributed in 3 upstairs and 1 on the ground floor, plus a back garden ideal for sharing family moments.',4,3,0,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1699675523_Abore_Ajuste_1920x790.mp4',NULL,0,2,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1719856564980.png',NULL,NULL,'2026-03-20 00:16:35','2026-03-20 00:16:35',0,NULL,'<iframe width=\'100%\' height=\'585\' src=\'https://armada.com.mx/sitio/clientes/javer/jalisco/arbore/blanc/360/\' frameborder=\'0\' allowfullscreen loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1730237044633.png',NULL),(170,39,'1',NULL,'Platino',NULL,'Descubre el modelo Platino con una distribucion espaciosa de 175 m2. Esta residencia inteligente cuenta con preparacion para instalar apagadores, bocinas y otros dispositivos compatibles con asistente de voz, que hacen tu vida mas comoda y practica. Ademas, ofrece un jardin trasero y un roof garden como areas sociales, brindando confort y seguridad para tu dia a dia.','Discover the Platinum model with a spacious 175 m2 layout. This smart home is equipped to install switches, speakers, and other voice assistant-compatible devices, making your life more comfortable and convenient. It also offers a rear garden and a roof garden as social areas, providing comfort and security for your daily life.',4,2,1,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/videos/desarollos/1699675523_Abore_Ajuste_1920x790.mp4',NULL,0,2,3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1719856723114.png',NULL,NULL,'2026-03-20 00:16:35','2026-03-20 00:16:35',0,NULL,'<iframe width=\'100%\' height=\'585\' src=\'https://armada.com.mx/sitio/clientes/javer/jalisco/arbore/platino/360/\' frameborder=\'0\' allowfullscreen loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1744227617394.png',NULL),(196,9,'1',NULL,'Milán',NULL,'El modelo Milán presenta un diseño funcional y versátil, con 3 recámaras, una de ellas en planta baja, ideal como espacio multiuso. Además, cuenta con un baño completo en esta planta, brindando mayor comodidad. Descubre estos acogedores espacios, pensados para transformar tu casa en el hogar que siempre quisiste.','The Milán model has a functional and versatile design, with 3 bedrooms, one of them on the first floor, ideal as a multipurpose space. It also has a full bathroom on this floor, providing greater comfort. Discover these cozy spaces, designed to transform your house into the home you always wanted.',3,2,0,'ready_to_move','0',NULL,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev',NULL,1,0,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1756926643897.jpg',NULL,NULL,'2026-03-19 17:23:01','2026-03-19 17:23:01',0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/images/media_1706921210656.png','<iframe width=\'100%\' height=\'540\' src=\'https://my.matterport.com/show/?m=SyP13zwtM3W\' frameborder=\'0\' allowfullscreen allow=\'xr-spatial-tracking\' loading=\"lazy\"></iframe>','{}',0,NULL,0,'https://javer-api-dev-page.s3.us-east-2.amazonaws.com/javer-api-dev/image-jpeg/1754435607474.jpg',NULL),(197,10,'1',NULL,'Aura Premier',NULL,'Con el prototipo Aura Premier, disfruta de espacios equilibrados que optimizan cada centímetro de tu nuevo hogar. Su ventanal en sala-comedor maximiza la iluminación y ventilación natural, creando un ambiente fresco y luminoso. Descubre estos acogedores espacios, pensados para transformar tu casa en el hogar que siempre quisiste.\n\n \n\nAdemás, tu hogar está equipado con un kit de domótica que incluye bocina, contactos, sensor y focos inteligentes que te permitirán automatizar y controlar aspectos clave de tu casa, la cual también cuenta con puerta de seguridad con cerradura inteligente asegurando funcionalidad y prevención desde el inicio.','With the Aura Premier prototype, enjoy balanced spaces that optimize every inch of your new home. Its large window in the living and dining areas maximizes natural light and ventilation, creating a fresh and bright atmosphere. Discover these inviting spaces, designed to transform your house into the home you\'ve always wanted.\n\nIn addition, your home is equipped with a home automation kit that includes a speaker, contacts, a sensor, and smart light bulbs that will allow you to automate and control key aspects of your home. It also features a security door with a smart lock, ensuring functionality and security f